/// @file actctx.cpp
/// @brief kernel32 activation contexts.
///
/// Microsoft Learn: CreateActCtxW, ACTCTXW, ActivateActCtx, DeactivateActCtx,
/// AddRefActCtx, ReleaseActCtx, GetCurrentActCtx, FindActCtxSectionStringW,
/// ACTCTX_SECTION_KEYED_DATA, QueryActCtxW. Contexts are generated by
/// winapi/common/sxs from the manifest; return values, error codes and the
/// keyed data a lookup produces are measured on Windows 11
/// (tests/oracle_data/actctx_probe.{x86,x64}.expected). Contract and known
/// gaps: .docs/contracts/sxs.md.

#include "winapi/kernel32/kernel32_ext.hpp"
#include "winapi/kernel32/error.hpp"
#include "winapi/kernel32/handle.hpp"
#include "winapi/kernel32/memory/memory.hpp"
#include "winapi/kernel32/module/module.hpp"
#include "winapi/core/marshaler.hpp"
#include "winapi/common/sxs/sxs_context.hpp"
#include "capsule/vfs/vfs.hpp"
#include "capsule/vfs/win32_full_path.hpp"
#include "core/pe/parser/manifest_info.hpp"
#include "core/pe/parser/pe_parser.hpp"
#include "ipc/ipc_gate.hpp"

#include <array>
#include <cstdio>
#include <mutex>

namespace vitreo::winapi {
namespace {

constexpr u32 kActCtxHandleBase = 0xAC000001u;

// winbase.h / winnt.h (SDK 10.0.26100.0).
constexpr u32 kFlagProcessorArchitectureValid = 0x01;
constexpr u32 kFlagLangIdValid = 0x02;
constexpr u32 kFlagAssemblyDirectoryValid = 0x04;
constexpr u32 kFlagResourceNameValid = 0x08;
constexpr u32 kFlagSetProcessDefault = 0x10;
constexpr u32 kFlagApplicationNameValid = 0x20;
constexpr u32 kFlagSourceIsAssemblyRef = 0x40;
constexpr u32 kFlagHModuleValid = 0x80;
constexpr u32 kActCtxKnownFlags = 0xFF;
constexpr u32 kDeactivateForceEarly = 0x1u;

constexpr u32 kFindReturnHActCtx = 0x1;
constexpr u32 kFindReturnFlags = 0x2;
constexpr u32 kFindReturnAssemblyMetadata = 0x4;

constexpr u32 kSectionAssemblyInformation = 1;
constexpr u32 kSectionDllRedirection = 2;
constexpr u32 kSectionComServerRedirection = 4;
constexpr u32 kSectionLast = 12;   // ACTIVATION_CONTEXT_SECTION_WINRT_ACTIVATABLE_CLASSES

constexpr u32 kQueryUseActive = 0x00000004;
constexpr u32 kQueryIsHModule = 0x00000008;
constexpr u32 kQueryIsAddress = 0x00000010;
constexpr u32 kQueryNoAddRef = 0x80000000;
constexpr u32 kInfoBasic = 1;

constexpr u16 kProcessorArchitectureIntel = 0;
constexpr u16 kProcessorArchitectureArm = 5;
constexpr u16 kProcessorArchitectureIa64 = 6;
constexpr u16 kProcessorArchitectureAmd64 = 9;
constexpr u16 kProcessorArchitectureArm64 = 12;

constexpr u32 kErrorNotSupported = 50;
constexpr u32 kErrorInsufficientBuffer = 122;

struct ActCtxStackEntry {
    u32 handle{0};
    u32 cookie{0};
};

thread_local std::vector<ActCtxStackEntry> t_actctx_stack;
thread_local u32 t_next_cookie{1};

void log_unimplemented(const char* api, const char* what) {
    static std::mutex lock;
    static std::vector<std::string> seen;
    std::lock_guard guard(lock);
    const std::string key = std::string(api) + what;
    for (const auto& s : seen) if (s == key) return;
    seen.push_back(key);
    std::fprintf(stderr, "[vitreo] UNIMPLEMENTED kernel32!%s: %s\n", api, what);
}

std::optional<std::vector<u8>> read_vfs_file(capsule::Vfs& vfs, const std::string& path) {
    auto opened = vfs.open(path, capsule::AccessMode::Read, capsule::ShareMode::Read,
                           capsule::CreationDisposition::OpenExisting);
    if (opened.is_err()) return std::nullopt;
    std::vector<u8> bytes;
    std::array<u8, 64 * 1024> chunk{};
    for (;;) {
        auto n = vfs.read(opened.value(), chunk);
        if (n.is_err()) { (void)vfs.close(opened.value()); return std::nullopt; }
        if (n.value() == 0) break;
        bytes.insert(bytes.end(), chunk.begin(), chunk.begin() + static_cast<std::ptrdiff_t>(n.value()));
    }
    (void)vfs.close(opened.value());
    return bytes;
}

std::string parent_dir(const std::string& path) {
    const usize sep = path.find_last_of("\\/");
    return sep == std::string::npos ? std::string{} : path.substr(0, sep);
}

const char* architecture_name(u16 arch) {
    switch (arch) {
        case kProcessorArchitectureIntel: return "x86";
        case kProcessorArchitectureAmd64: return "amd64";
        case kProcessorArchitectureArm64: return "arm64";
        case kProcessorArchitectureArm: return "arm";
        case kProcessorArchitectureIa64: return "ia64";
        default: return nullptr;
    }
}

// x86 / x64 field offsets of ACTCTX_SECTION_KEYED_DATA (winnt.h; the probe's
// cbSize boundaries: x86 hActCtx 32, ulFlags 40, full 64; x64 56 / 68 / 112).
struct KeyedLayout {
    u32 ver, data, length, global, global_length, base, total, hactctx, roster, flags, metadata, full;
};
constexpr KeyedLayout kKeyed32{4, 8, 12, 16, 20, 24, 28, 32, 36, 40, 44, 64};
constexpr KeyedLayout kKeyed64{4, 8, 16, 24, 32, 40, 48, 56, 64, 68, 72, 112};

}  // namespace

bool Kernel32ExtManager::materialize_actctx_section(Marshaler& m, ActivationContext& context) {
    if (context.section != 0 || context.data == nullptr) return context.data != nullptr;
    const sxs::DllRedirectionSection section = sxs::build_dll_redirection_section(*context.data);
    const u32 alloc = static_cast<u32>((section.bytes.size() + 0xFFF) & ~usize{0xFFF});
    GuestAddr base = 0;
    if (m_virtual_memory_manager != nullptr) {
        base = static_cast<GuestAddr>(m_virtual_memory_manager->virtual_alloc(
            0, alloc, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE));
    }
    if (base == 0) return false;
    if (m.memory().write_bytes(base, reinterpret_cast<const Byte*>(section.bytes.data()), section.bytes.size()).is_err()) {
        (void)m_virtual_memory_manager->virtual_free(base, 0, MEM_RELEASE);
        return false;
    }
    context.section = base;
    context.section_size = static_cast<u32>(section.bytes.size());
    context.section_alloc = alloc;
    context.entries = section.entries;
    return true;
}

void Kernel32ExtManager::set_process_default_activation_context(std::shared_ptr<const sxs::ContextData> context) {
    std::lock_guard lock(m_actctx_mutex);
    ActivationContext entry;
    entry.data = std::move(context);
    m_default_actctx = std::move(entry);
}

std::optional<std::string> Kernel32ExtManager::sxs_redirect_dll(std::string_view base_name) {
    std::lock_guard lock(m_actctx_mutex);
    const ActivationContext* context = nullptr;
    if (!t_actctx_stack.empty() && t_actctx_stack.back().handle != 0) {
        if (auto it = m_actctxs.find(t_actctx_stack.back().handle); it != m_actctxs.end()) context = &it->second;
    } else if (m_default_actctx) {
        context = &*m_default_actctx;
    }
    if (context == nullptr || context->data == nullptr) return std::nullopt;
    return context->data->redirect_dll(base_name);
}

void Kernel32ExtManager::create_actctx(Marshaler& m, bool wide) {
    const GuestAddr info = m.arg_ptr(0);
    const bool x64 = m.cpu_is_64bit();
    const u32 ptr = x64 ? 8u : 4u;
    // ACTCTX: cbSize, dwFlags, lpSource, wProcessorArchitecture, wLangId,
    // lpAssemblyDirectory, lpResourceName, lpApplicationName, hModule.
    const u32 off_source = 8;
    const u32 off_arch = 8 + ptr;
    const u32 off_lang = off_arch + 2;
    const u32 off_dir = x64 ? 24u : 16u;
    const u32 off_resource = off_dir + ptr;
    const u32 off_appname = off_resource + ptr;
    const u32 off_module = off_appname + ptr;
    const auto fail = [&](u32 error) {
        set_last_error(error);
        m.set_return(m.cpu_is_64bit() ? ~u64{0} : u64{INVALID_HANDLE});
    };
    if (info == 0) {
        fail(error_codes::ERROR_INVALID_PARAMETER);
        return;
    }
    const u32 cb_size = static_cast<u32>(m.read_u32(info).value_or(0));
    const u32 flags = static_cast<u32>(m.read_u32(info + 4).value_or(0));
    // Measured: cbSize 0 and an unknown flag bit are ERROR_INVALID_PARAMETER.
    if (cb_size < off_arch || (flags & ~kActCtxKnownFlags) != 0) {
        fail(error_codes::ERROR_INVALID_PARAMETER);
        return;
    }
    const auto field_present = [&](u32 offset, u32 size) { return cb_size >= offset + size; };
    const auto read_string = [&](GuestAddr p) -> std::string {
        if (p == 0) return {};
        auto text = wide ? m.read_wide_string(p) : m.read_ansi_string(p);
        return text.is_ok() ? text.value() : std::string{};
    };
    if ((flags & kFlagSourceIsAssemblyRef) != 0) {
        log_unimplemented("CreateActCtx", "ACTCTX_FLAG_SOURCE_IS_ASSEMBLYREF (an assembly reference as the source)");
        fail(kErrorNotSupported);
        return;
    }

    std::string source = read_string(m.read_ptr(info + off_source).value_or(0));
    std::string architecture = x64 ? "amd64" : "x86";
    if ((flags & kFlagProcessorArchitectureValid) != 0) {
        if (!field_present(off_arch, 2)) { fail(error_codes::ERROR_INVALID_PARAMETER); return; }
        const char* name = architecture_name(static_cast<u16>(m.read_u32(info + off_arch).value_or(0) & 0xFFFF));
        if (name == nullptr) { fail(error_codes::ERROR_INVALID_PARAMETER); return; }
        architecture = name;
    }
    if ((flags & kFlagLangIdValid) != 0) {
        if (!field_present(off_lang, 2)) { fail(error_codes::ERROR_INVALID_PARAMETER); return; }
        log_unimplemented("CreateActCtx", "ACTCTX_FLAG_LANGID_VALID: wLangId does not select a culture for probing");
    }
    std::string assembly_dir;
    if ((flags & kFlagAssemblyDirectoryValid) != 0) {
        if (!field_present(off_dir, ptr)) { fail(error_codes::ERROR_INVALID_PARAMETER); return; }
        assembly_dir = read_string(m.read_ptr(info + off_dir).value_or(0));
    }
    std::optional<u16> resource_id;
    if ((flags & kFlagResourceNameValid) != 0) {
        if (!field_present(off_resource, ptr)) { fail(error_codes::ERROR_INVALID_PARAMETER); return; }
        const GuestAddr resource = m.read_ptr(info + off_resource).value_or(0);
        if (resource > 0xFFFF) {
            log_unimplemented("CreateActCtx", "a manifest resource identified by a string name");
            fail(kErrorNotSupported);
            return;
        }
        resource_id = static_cast<u16>(resource);
    }
    if ((flags & kFlagApplicationNameValid) != 0) {
        if (!field_present(off_appname, ptr)) { fail(error_codes::ERROR_INVALID_PARAMETER); return; }
        log_unimplemented("CreateActCtx", "ACTCTX_FLAG_APPLICATION_NAME_VALID: no <application>.config is applied");
    }
    if ((flags & kFlagHModuleValid) != 0) {
        if (!field_present(off_module, ptr)) { fail(error_codes::ERROR_INVALID_PARAMETER); return; }
        const GuestAddr module = m.read_ptr(info + off_module).value_or(0);
        const std::string* path = m_module_manager != nullptr ? m_module_manager->module_path(module) : nullptr;
        if (path == nullptr) { fail(error_codes::ERROR_INVALID_HANDLE); return; }
        source = *path;
    }
    if (source.empty()) {
        fail(error_codes::ERROR_INVALID_PARAMETER);
        return;
    }
    if (auto full = capsule::win32_full_path(source, m_current_directory)) source = full->path;

    const auto bytes = read_vfs_file(m_vfs, source);
    if (!bytes) {
        fail(error_codes::ERROR_FILE_NOT_FOUND);  // measured: missing source
        return;
    }
    std::span<const u8> manifest(*bytes);
    if (bytes->size() >= 2 && (*bytes)[0] == 'M' && (*bytes)[1] == 'Z') {
        // A PE source: its RT_MANIFEST resource (Learn ACTCTX lpResourceName;
        // without one, CREATEPROCESS_MANIFEST_RESOURCE_ID).
        auto pe = pe::parse_pe(*bytes);
        if (pe.is_err()) { fail(sxs::kErrorSxsCantGenActCtx); return; }
        manifest = pe::pe_manifest_resource(*bytes, pe.value(), resource_id.value_or(1));
        if (manifest.empty()) { fail(error_codes::ERROR_RESOURCE_TYPE_NOT_FOUND); return; }
    }

    sxs::ContextRequest request;
    request.manifest = manifest;
    request.manifest_path = source;
    request.root_directory = parent_dir(source);
    request.application_dir = assembly_dir.empty() ? parent_dir(source) : assembly_dir;
    request.architecture = architecture;
    const sxs::ContextResult generated = sxs::build_context(m_vfs, request);
    if (!generated.data) {
        std::fprintf(stderr, "[vitreo] sxs: CreateActCtx(%s): %s\n", source.c_str(), generated.detail.c_str());
        fail(sxs::kErrorSxsCantGenActCtx);  // measured for an unresolvable dependency
        return;
    }
    auto data = std::make_shared<const sxs::ContextData>(std::move(*generated.data));

    if ((flags & kFlagSetProcessDefault) != 0) {
        std::lock_guard lock(m_actctx_mutex);
        if (m_default_actctx) {
            set_last_error(sxs::kErrorSxsProcessDefaultAlreadySet);
            m.set_return(m.cpu_is_64bit() ? ~u64{0} : u64{INVALID_HANDLE});
            return;
        }
        ActivationContext entry;
        entry.data = std::move(data);
        m_default_actctx = std::move(entry);
        m.set_return(0);  // measured: NULL, last error untouched
        return;
    }

    u32 handle = 0;
    {
        std::lock_guard lock(m_actctx_mutex);
        handle = kActCtxHandleBase + m_next_actctx;
        ++m_next_actctx;
        ActivationContext entry;
        entry.data = std::move(data);
        m_actctxs.emplace(handle, std::move(entry));
    }
    ipc::ipc_log("CreateActCtx%s flags=0x%x source='%s' -> 0x%x", wide ? "W" : "A", flags, source.c_str(), handle);
    // last_error_on_success_probe: CreateActCtx clears the last error on success.
    set_last_error(error_codes::ERROR_SUCCESS);
    m.set_return(handle);
}

void Kernel32ExtManager::impl_CreateActCtxA(Marshaler& m) {
    create_actctx(m, false);
}

void Kernel32ExtManager::impl_CreateActCtxW(Marshaler& m) {
    create_actctx(m, true);
}

void Kernel32ExtManager::impl_ActivateActCtx(Marshaler& m) {
    const u32 handle = static_cast<u32>(m.arg(0));
    const GuestAddr cookie_ptr = m.arg_ptr(1);
    if (cookie_ptr == 0) {
        set_last_error(error_codes::ERROR_INVALID_PARAMETER);
        m.set_return(0);
        return;
    }
    if (handle != 0) {
        std::lock_guard lock(m_actctx_mutex);
        if (m_actctxs.find(handle) == m_actctxs.end()) {
            set_last_error(error_codes::ERROR_INVALID_HANDLE);
            m.set_return(0);
            return;
        }
    }
    const u32 cookie = t_next_cookie++;
    t_actctx_stack.push_back(ActCtxStackEntry{handle, cookie});
    if (m.cpu_is_64bit()) {
        if (m.write_u64(cookie_ptr, cookie).is_err()) {
            t_actctx_stack.pop_back();
            set_last_error(error_codes::ERROR_INVALID_PARAMETER);
            m.set_return(0);
            return;
        }
    } else if (m.write_u32(cookie_ptr, cookie).is_err()) {
        t_actctx_stack.pop_back();
        set_last_error(error_codes::ERROR_INVALID_PARAMETER);
        m.set_return(0);
        return;
    }
    m.set_return(1);
}

void Kernel32ExtManager::impl_DeactivateActCtx(Marshaler& m) {
    const u32 flags = static_cast<u32>(m.arg(0));
    const u32 cookie = static_cast<u32>(m.arg(1));
    if (t_actctx_stack.empty()) {
        set_last_error(error_codes::ERROR_INVALID_PARAMETER);
        m.set_return(0);
        return;
    }
    if ((flags & kDeactivateForceEarly) != 0) {
        while (!t_actctx_stack.empty() &&
               t_actctx_stack.back().cookie != cookie) {
            t_actctx_stack.pop_back();
        }
    }
    if (t_actctx_stack.empty() || t_actctx_stack.back().cookie != cookie) {
        set_last_error(error_codes::ERROR_INVALID_PARAMETER);
        m.set_return(0);
        return;
    }
    t_actctx_stack.pop_back();
    m.set_return(1);
}

void Kernel32ExtManager::impl_AddRefActCtx(Marshaler& m) {
    // VOID AddRefActCtx(HANDLE hActCtx)
    const u32 handle = static_cast<u32>(m.arg(0));
    std::lock_guard lock(m_actctx_mutex);
    if (auto it = m_actctxs.find(handle); it != m_actctxs.end()) ++it->second.refs;
}

void Kernel32ExtManager::impl_ReleaseActCtx(Marshaler& m) {
    const u32 handle = static_cast<u32>(m.arg(0));
    if (handle == 0 || handle == INVALID_HANDLE) return;
    std::lock_guard lock(m_actctx_mutex);
    auto it = m_actctxs.find(handle);
    if (it == m_actctxs.end()) return;
    if (it->second.refs > 0) --it->second.refs;
    if (it->second.refs == 0) {
        if (it->second.section != 0 && m_virtual_memory_manager != nullptr) {
            (void)m_virtual_memory_manager->virtual_free(it->second.section, 0, MEM_RELEASE);
        }
        m_actctxs.erase(it);
    }
}

void Kernel32ExtManager::impl_GetCurrentActCtx(Marshaler& m) {
    const GuestAddr out = m.arg_ptr(0);
    if (out == 0) {
        set_last_error(error_codes::ERROR_INVALID_PARAMETER);
        m.set_return(0);
        return;
    }
    // Measured: with nothing activated (process default or not) the call
    // succeeds with a NULL handle and leaves the last error alone.
    u32 handle = 0;
    if (!t_actctx_stack.empty() && t_actctx_stack.back().handle != 0) {
        handle = t_actctx_stack.back().handle;
        std::lock_guard lock(m_actctx_mutex);
        auto it = m_actctxs.find(handle);
        if (it == m_actctxs.end()) {
            handle = 0;
        } else {
            ++it->second.refs;
        }
    }
    const bool ok = m.cpu_is_64bit() ? m.write_u64(out, handle).is_ok() : m.write_u32(out, handle).is_ok();
    if (!ok) {
        set_last_error(error_codes::ERROR_INVALID_PARAMETER);
        m.set_return(0);
        return;
    }
    m.set_return(1);
}

void Kernel32ExtManager::find_actctx_section_string(Marshaler& m, bool wide) {
    // BOOL FindActCtxSectionString(DWORD dwFlags, const GUID* lpExtensionGuid,
    //   ULONG ulSectionId, LPCTSTR lpStringToFind,
    //   PACTCTX_SECTION_KEYED_DATA ReturnedData)
    const u32 flags = static_cast<u32>(m.arg(0));
    const GuestAddr extension = m.arg_ptr(1);
    const u32 section_id = static_cast<u32>(m.arg(2));
    const GuestAddr name_ptr = m.arg_ptr(3);
    const GuestAddr out = m.arg_ptr(4);
    const KeyedLayout& k = m.cpu_is_64bit() ? kKeyed64 : kKeyed32;
    const auto fail = [&](u32 error) {
        set_last_error(error);
        m.set_return(0);
    };
    if ((flags & ~(kFindReturnHActCtx | kFindReturnFlags | kFindReturnAssemblyMetadata)) != 0 || out == 0 ||
        name_ptr == 0) {
        fail(error_codes::ERROR_INVALID_PARAMETER);  // measured: flag 8, NULL data, NULL name
        return;
    }
    const u32 cb_size = static_cast<u32>(m.read_u32(out).value_or(0));
    u32 needed = k.roster + 4;
    if ((flags & kFindReturnFlags) != 0) needed = k.flags + 4;
    if ((flags & kFindReturnAssemblyMetadata) != 0) needed = k.full;
    if (cb_size < needed) {
        fail(error_codes::ERROR_INVALID_PARAMETER);  // measured boundaries
        return;
    }
    if (extension != 0) {
        fail(sxs::kErrorSxsSectionNotFound);  // measured: no extension sections
        return;
    }
    if (section_id == 0 || section_id > kSectionLast) {
        fail(sxs::kErrorSxsSectionNotFound);  // measured: section 99
        return;
    }
    if (section_id != kSectionDllRedirection) {
        if (section_id == kSectionAssemblyInformation) {
            log_unimplemented("FindActCtxSectionString", "the assembly information section");
        }
        // Vitreo's contexts carry only DLL redirection: no window class or
        // COM data is generated (manifests that declare it are logged when
        // the context is built). Measured for undeclared names: COM server
        // 14002, the other string sections 14007.
        fail(section_id == kSectionComServerRedirection ? 14002u : sxs::kErrorSxsKeyNotFound);
        return;
    }
    if ((flags & kFindReturnAssemblyMetadata) != 0) {
        log_unimplemented("FindActCtxSectionString", "FIND_ACTCTX_SECTION_KEY_RETURN_ASSEMBLY_METADATA");
        fail(kErrorNotSupported);
        return;
    }
    auto name = wide ? m.read_wide_string(name_ptr) : m.read_ansi_string(name_ptr);
    if (name.is_err()) {
        fail(error_codes::ERROR_INVALID_PARAMETER);
        return;
    }

    std::lock_guard lock(m_actctx_mutex);
    ActivationContext* context = nullptr;
    u32 handle = 0;
    if (!t_actctx_stack.empty() && t_actctx_stack.back().handle != 0) {
        handle = t_actctx_stack.back().handle;
        if (auto it = m_actctxs.find(handle); it != m_actctxs.end()) context = &it->second;
    } else if (m_default_actctx) {
        context = &*m_default_actctx;   // reported as a NULL hActCtx (measured)
    }
    if (context == nullptr || context->data == nullptr) {
        fail(sxs::kErrorSxsKeyNotFound);  // measured: no context at all
        return;
    }
    if (!materialize_actctx_section(m, *context)) {
        fail(error_codes::ERROR_NOT_ENOUGH_MEMORY);
        return;
    }
    const auto entry = context->entries.find(sxs::to_lower(name.value()));
    if (entry == context->entries.end()) {
        fail(sxs::kErrorSxsKeyNotFound);
        return;
    }
    const auto put_ptr = [&](u32 offset, u64 value) {
        if (m.cpu_is_64bit()) (void)m.write_u64(out + offset, value);
        else (void)m.write_u32(out + offset, static_cast<u32>(value));
    };
    (void)m.write_u32(out + k.ver, 1);
    put_ptr(k.data, context->section + entry->second.data_offset);
    (void)m.write_u32(out + k.length, entry->second.data_length);
    put_ptr(k.global, 0);
    (void)m.write_u32(out + k.global_length, 0);
    put_ptr(k.base, context->section);
    (void)m.write_u32(out + k.total, context->section_size);
    if ((flags & kFindReturnHActCtx) != 0 && handle != 0) {
        ++context->refs;   // measured: the returned handle carries a reference
        put_ptr(k.hactctx, handle);
    } else {
        put_ptr(k.hactctx, 0);
    }
    (void)m.write_u32(out + k.roster, entry->second.roster_index);
    if (cb_size >= k.flags + 4) (void)m.write_u32(out + k.flags, 0);
    m.set_return(1);
}

void Kernel32ExtManager::impl_FindActCtxSectionStringA(Marshaler& m) {
    find_actctx_section_string(m, false);
}

void Kernel32ExtManager::impl_FindActCtxSectionStringW(Marshaler& m) {
    find_actctx_section_string(m, true);
}

void Kernel32ExtManager::impl_QueryActCtxW(Marshaler& m) {
    // BOOL QueryActCtxW(DWORD dwFlags, HANDLE hActCtx, PVOID pvSubInstance,
    //   ULONG ulInfoClass, PVOID pvBuffer, SIZE_T cbBuffer,
    //   SIZE_T* pcbWrittenOrRequired)
    const u32 flags = static_cast<u32>(m.arg(0));
    u32 handle = static_cast<u32>(m.arg(1));
    const u32 info_class = static_cast<u32>(m.arg(3));
    const GuestAddr buffer = m.arg_ptr(4);
    const u64 cb_buffer = m.arg(5);
    const GuestAddr written = m.arg_ptr(6);
    const bool x64 = m.cpu_is_64bit();
    const auto fail = [&](u32 error) {
        set_last_error(error);
        m.set_return(0);
    };
    const u32 selectors = flags & (kQueryUseActive | kQueryIsHModule | kQueryIsAddress);
    if ((flags & ~(selectors | kQueryNoAddRef)) != 0 || (selectors & (selectors - 1)) != 0) {
        fail(error_codes::ERROR_INVALID_PARAMETER);
        return;
    }
    if ((flags & (kQueryIsHModule | kQueryIsAddress)) != 0) {
        log_unimplemented("QueryActCtxW", "QUERY_ACTCTX_FLAG_ACTCTX_IS_HMODULE / _IS_ADDRESS (per-module contexts)");
        fail(kErrorNotSupported);
        return;
    }
    if ((flags & kQueryUseActive) != 0) {
        handle = (!t_actctx_stack.empty()) ? t_actctx_stack.back().handle : 0;
    }
    if (info_class != kInfoBasic) {
        log_unimplemented("QueryActCtxW", "information classes other than ActivationContextBasicInformation");
        fail(kErrorNotSupported);
        return;
    }
    if (handle != 0) {
        std::lock_guard lock(m_actctx_mutex);
        if (m_actctxs.find(handle) == m_actctxs.end()) {
            fail(error_codes::ERROR_INVALID_PARAMETER);
            return;
        }
    }
    // ACTIVATION_CONTEXT_BASIC_INFORMATION { HANDLE hActCtx; DWORD dwFlags; }
    const u32 needed = x64 ? 16u : 8u;   // measured
    if (written != 0) {
        if (x64) (void)m.write_u64(written, needed);
        else (void)m.write_u32(written, needed);
    }
    if (buffer == 0 || cb_buffer < needed) {
        fail(kErrorInsufficientBuffer);
        return;
    }
    if (handle != 0 && (flags & kQueryNoAddRef) == 0) {
        std::lock_guard lock(m_actctx_mutex);
        if (auto it = m_actctxs.find(handle); it != m_actctxs.end()) ++it->second.refs;
    }
    if (x64) {
        (void)m.write_u64(buffer, handle);
        (void)m.write_u32(buffer + 8, 0);
    } else {
        (void)m.write_u32(buffer, handle);
        (void)m.write_u32(buffer + 4, 0);
    }
    m.set_return(1);
}

} // namespace vitreo::winapi
